"""Public product copy for the authenticated start page; no candidate facts or counts."""
import html
CSS='''*{box-sizing:border-box}:root{color-scheme:light;--bg:#f7f6f3;--fg:#1f1c19;--surface:#fff;--border:#dfddd8;--muted:#5e5851;--link:#15569a;--accent:#174b70}body{margin:0;background:var(--bg);color:var(--fg);font:16px/1.55 system-ui}main{max-width:1080px;margin:auto;padding:18px 24px}a{color:var(--link);text-underline-offset:3px;cursor:pointer}a:focus-visible{outline:3px solid var(--link);outline-offset:4px}h1{font-size:clamp(24px,4vw,32px);line-height:1.13;margin:12px 0}h2{font-size:23px;margin:0 0 12px}h3{font-size:18px;margin:0 0 6px}p{margin:0 0 14px}.eyebrow{font-size:13px;letter-spacing:.11em;text-transform:uppercase;color:var(--muted)}.intro{max-width:710px;color:var(--muted);font-size:18px}.workspaces{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:0 0 24px}.workspace,.step{background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:22px}.workspace:first-child{border-color:var(--link)}.action{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:10px 12px;border:1px solid var(--border);border-radius:9px;font-weight:650;text-decoration:none;transition:background .15s,box-shadow .15s,transform .1s}.primary{background:var(--accent);color:white;border-color:var(--accent)}.action:hover{box-shadow:0 0 0 2px var(--link)}.action:active{transform:translateY(1px);box-shadow:inset 0 0 0 2px var(--link)}.shortcuts{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.shortcuts a{display:inline-flex;align-items:center;min-height:44px;padding:6px 9px}.shortcuts a:hover{background:var(--bg);border-radius:6px}.shortcuts a:active{background:var(--border)}.resume{color:var(--muted);padding:0 0 22px;border-bottom:1px solid var(--border);margin-bottom:28px}.steps{list-style:none;padding:0;margin:18px 0 32px;display:grid;grid-template-columns:repeat(3,1fr);gap:12px;counter-reset:step}.step{position:relative;padding:18px}.step:before{counter-increment:step;content:counter(step);display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border:1px solid var(--link);color:var(--link);border-radius:50%;font-size:14px;margin-bottom:10px}.step p{font-size:15px;color:var(--muted);margin:0}.features{display:grid;grid-template-columns:1fr 1fr;gap:0 28px;margin:0}.features div{padding:15px 0;border-top:1px solid var(--border)}dt{font-weight:650}dd{margin:3px 0 0;color:var(--muted);font-size:15px}.note{color:var(--muted);font-size:14px;margin-top:22px}footer{border-top:1px solid var(--border);padding-top:20px;margin-top:30px;color:var(--muted);font-size:13px}@media(max-width:650px){main{padding:10px 12px}.features{grid-template-columns:1fr}.steps{grid-template-columns:1fr}.step{padding:16px 16px 16px 56px}.step:before{position:absolute;left:16px;top:17px}.workspace{padding:20px}.action{width:100%}}@media(prefers-color-scheme:dark){:root{color-scheme:dark;--bg:#0a0a0a;--fg:#fafafa;--surface:#161616;--border:#292929;--muted:#a1a1aa;--link:#8fc5f5;--accent:#174b70}}@media(prefers-reduced-motion:reduce){.action{transition:none}}'''
STEPS=[('Check your foundation','Keep Profile and CV current. Revisit them when your goals or experience change.'),('Find opportunities','Run Search and review matches and source coverage. Adjust filters when needed.'),('Choose what to pursue','Use Pipeline to revisit saved opportunities and open the original posting.'),('Evaluate the fit','Supply the full posting to Evaluate job. Review the result and record it as Evaluated in Documents.'),('Prepare your application','Create a tailored draft, review its claims and quality checks, and export a PDF from Documents.'),('Apply, track and prepare','Submit on the employer’s site yourself, then update Applications. Use Interview prep for plans, practice and debriefs.')]
FEATURES=[('Profile & CV','Your targeting preferences and the source-backed experience used in drafts.'),('Search','Find jobs from configured company boards; review filters, coverage and saved runs.'),('Pipeline','Saved opportunities to consider; adding a job here does not apply for it.'),('Applications','Evaluated and submitted job records, with status and notes you control.'),('Documents','Current profiles, reviews, drafts and PDFs, plus clearly dated archives.'),('Assistant','Discuss opportunities or create and edit career documents using confirmed facts.'),('Interview prep','Build a prep plan, practice questions with feedback, or debrief an interview.'),('Quality review & PDF','Review exact document text, diagnostic keyword, number and title checks before export.')]
def start_page():
 esc=lambda s:html.escape(s,quote=True)
 cards=''.join('<a class="action primary" href="/'+slug+'/workspace">'+name+'’s workspace</a>' for slug,name in [('brad','Brad'),('steve','Steve')])
 steps=''.join('<li class="step"><h3>'+esc(title)+'</h3><p>'+esc(text)+'</p></li>' for title,text in STEPS)
 features=''.join('<div><dt>'+esc(title)+'</dt><dd>'+esc(text)+'</dd></div>' for title,text in FEATURES)
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>Career Ops · Pick up your job search</title><link rel="stylesheet" href="/assets/home.css"></head><body><main><nav class="workspaces" aria-label="Choose your workspace">'+cards+'</nav><section aria-labelledby="workflow"><h1 id="workflow">Your job-search path</h1><p class="note">Use this as a guide, not a checklist to repeat every visit.</p><ol class="steps">'+steps+'</ol></section><section aria-labelledby="features"><h2 id="features">What each feature is for</h2><dl class="features">'+features+'</dl><p class="note">Keep the master CV factual. Review AI drafts and uncertain job details before using them. Quality checks help spot issues; they don’t verify every claim or guarantee ATS success.</p></section><footer>Shared login · Separate Brad and Steve workspaces · Live documents are on the VPS<br>You choose what to save, review and submit. Nothing automatically sends an application.</footer></main></body></html>'
